import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import ProductForm from "./components/product/ProductForm";
import ProductList from "./components/product/ProductList";
import EmployeeForm from "./components/employee/EmployeeForm";
import EmployeeList from "./components/employee/EmployeeList";
import UserForm from "./components/user/UserForm";
import UserList from "./components/user/UserList";
import Login from "./components/login/Login";
import PrivateRouteWrapper from "./components/login/PrivateRouteWrapper";
import { useEffect } from "react";
import { setAuthToken } from "./redux/root/api";

function App() {
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) setAuthToken(token);
  }, []);

  return (
    <Router>
      <Routes>
        {/* Public route */}
        <Route path="/login" element={<Login />} />

        {/* Protected routes */}
        <Route
          path="/"
          element={
            <PrivateRouteWrapper>
              <EmployeeList />
            </PrivateRouteWrapper>
          }
        />

        <Route
          path="/add"
          element={
            <PrivateRouteWrapper>
              <EmployeeForm />
            </PrivateRouteWrapper>
          }
        />

        <Route
          path="/edit/:id"
          element={
            <PrivateRouteWrapper>
              <EmployeeForm />
            </PrivateRouteWrapper>
          }
        />

        <Route
          path="/products"
          element={
            <PrivateRouteWrapper>
              <ProductList />
            </PrivateRouteWrapper>
          }
        />

        <Route
          path="/products/add"
          element={
            <PrivateRouteWrapper>
              <ProductForm />
            </PrivateRouteWrapper>
          }
        />

        {/* New User routes */}
        <Route
          path="/users"
          element={
            <PrivateRouteWrapper>
              <UserList />
            </PrivateRouteWrapper>
          }
        />

        <Route
          path="/users/add"
          element={
            <PrivateRouteWrapper>
              <UserForm />
            </PrivateRouteWrapper>
          }
        />

        <Route
          path="/users/edit/:id"
          element={
            <PrivateRouteWrapper>
              <UserForm />
            </PrivateRouteWrapper>
          }
        />

        {/* Redirect to login for any other route */}
        <Route path="*" element={<Navigate to="/login" />} />
      </Routes>
    </Router>
  );
}

export default App;
